<template><div class="ke-admin"><PageHero title="管理后台" subtitle="把平台的日常运营，整理得清清楚楚。" /><div class="ke-ad-inner"><div class="ke-ad-stats"><div v-for="item in counters" :key="item.key" class="ke-ad-stat"><b>{{ stats[item.key] ?? '—' }}</b><span>{{ item.label }}</span></div></div><div class="admin-topline"><nav class="ke-ad-tabs" aria-label="管理分类"><button v-for="item in tabs" :key="item.key" :class="{ on: tab === item.key }" @click="tab = item.key">{{ item.label }}</button></nav><RouterLink to="/app/kb-admin" class="jade-link">知识库管理 <ArrowIcon /></RouterLink></div><form v-if="tab==='houses'" class="admin-topline" @submit.prevent="page=1;load()"><input v-model.trim="keyword" aria-label="搜索房源" placeholder="房源标题或城市"/><select v-model="filter"><option value="ALL">全部状态</option><option value="PENDING">待审核</option><option value="APPROVED">已上架</option><option value="REJECTED">未通过</option><option value="OFFLINE">已下架</option></select><button>查询</button><button type="button" :disabled="page<=1" @click="page--;load()">上一页</button><span>第{{page}}页 · 共{{total}}条</span><button type="button" :disabled="page*50>=total" @click="page++;load()">下一页</button></form><div v-if="error" class="admin-state"><p>{{ error }}</p><button class="jade-button" @click="load">重新加载</button></div><div v-else-if="loading" class="admin-state" aria-busy="true">正在整理平台数据……</div><div v-else-if="!rows.length" class="admin-state">当前分类还没有记录。</div><div v-else class="ke-ad-table"><table><thead><tr><th v-for="col in columns" :key="col.key">{{ col.label }}</th><th>操作</th><th v-if="tab === 'houses' || tab === 'guides'">查看</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td v-for="col in columns" :key="col.key" :class="{ 'admin-title': col.key === 'title' || col.key === 'content' }">{{ display(row[col.key], col.key) }}</td><td><ModerationAction :row="row" :kind="tab" @changed="refresh" /></td><td v-if="tab === 'houses'"><RouterLink :to="'/detail/' + row.id">房源详情 ↗</RouterLink></td><td v-if="tab === 'guides'"><RouterLink :to="'/app/guide-detail/' + row.id">阅读攻略 ↗</RouterLink></td></tr></tbody></table></div></div></div></template>
<script setup>
import ModerationAction from './ModerationAction.vue'
import request from '../api/index'
import { ref, computed, watch, onMounted } from 'vue'
import { adminApi } from '../api/modules'
import { houseApi } from '../api/house'
import PageHero from './PageHero.vue'
import ArrowIcon from './ArrowIcon.vue'
const keyword=ref(''),filter=ref('ALL'),page=ref(1),total=ref(0)
const tab=ref('houses'),stats=ref({}),rows=ref([]),loading=ref(true),error=ref('')
const counters=[{key:'totalHouses',label:'房源'},{key:'totalUsers',label:'用户'},{key:'totalFavorites',label:'收藏'},{key:'totalReviews',label:'评价'},{key:'totalGuides',label:'攻略'},{key:'totalContracts',label:'合同审查'}]
const tabs=[{key:'houses',label:'房源管理'},{key:'users',label:'用户管理'},{key:'reviews',label:'评价记录'},{key:'guides',label:'租房攻略'},{key:'contracts',label:'合同记录'},{key:'reports',label:'举报处理'}]
const definitions={reports:[['id','编号'],['houseTitle','房源'],['category','类型'],['content','举报内容'],['status','处理状态']],houses:[['id','编号'],['title','房源'],['city','城市'],['price','月租金'],['status','状态']],users:[['id','编号'],['username','用户名'],['role','角色'],['status','状态']],reviews:[['id','编号'],['reviewerName','评价人'],['landlordName','房东'],['score','评分'],['content','评价内容'],['status','状态']],guides:[['id','编号'],['title','标题'],['category','分类'],['authorName','作者'],['status','状态']],contracts:[['id','编号'],['title','合同'],['userName','用户'],['overallRisk','总体风险'],['status','状态']]}
const columns=computed(()=>definitions[tab.value].map(([key,label])=>({key,label})))
let version=0
async function load(){const current=++version;loading.value=true;error.value='';try{const result=tab.value==='houses'?await request.get('/trust/queue',{params:{status:filter.value,page:page.value,keyword:keyword.value}}):tab.value==='reports'?await request.get('/trust/reports',{params:{all:true}}):await adminApi[tab.value]();if(current!==version)return;total.value=result.data?.total||0;rows.value=Array.isArray(result.data)?result.data:result.data?.list || []}catch(e){if(current===version)error.value=e.message || '数据加载失败，请稍后重试。'}finally{if(current===version)loading.value=false}}
function display(value,key){if(value===undefined||value===null||value==='')return '—';if(key==='price')return `¥ ${Number(value).toLocaleString('zh-CN')}`;if(key==='role')return {ADMIN:'管理员',LANDLORD:'房东',TENANT:'租客'}[value] || value;if(key==='status')return {APPROVED:'已通过',PENDING:'待审核',REJECTED:'未通过',published:'已发布',draft:'草稿',OFFLINE:'已下架',RESOLVED:'已处理',DISMISSED:'未采纳'}[value] || (value===1?'正常':value===0?'停用':value);return value}
function refresh(){load();adminApi.stats().then(r=>stats.value=r.data||{}).catch(()=>{})}
watch(tab,()=>{page.value=1;load()});onMounted(()=>{load();adminApi.stats().then(r=>{stats.value=r.data || {}}).catch(()=>{})})
</script>
<style scoped>
.ke-admin{background:var(--jade-paper);min-height:calc(100dvh - var(--header-height))}.ke-ad-inner{max-width:1450px;margin:auto;padding:35px var(--page-gutter) 70px}.ke-ad-stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px;margin-bottom:35px}.ke-ad-stat{border:1px solid var(--jade-line);padding:25px;background:#fffefa;border-radius:4px;text-align:center}.ke-ad-stat b{display:block;font-size:32px;color:var(--jade-600);font-weight:500}.ke-ad-stat span{font-size:11px;color:var(--jade-muted)}.admin-topline{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:20px}.ke-ad-tabs{display:flex;gap:8px;flex-wrap:wrap}.ke-ad-tabs button{border:1px solid var(--jade-line);background:none;padding:9px 16px;color:var(--jade-muted);border-radius:3px;font-size:12px}.ke-ad-tabs button.on{background:var(--jade-900);color:white;border-color:var(--jade-900)}.admin-topline .jade-link{font-size:12px;white-space:nowrap}.ke-ad-table{border:1px solid var(--jade-line);border-radius:4px;overflow:auto;background:#fffefa}.ke-ad-table table{border-collapse:collapse;width:100%;font-size:12px;white-space:nowrap}.ke-ad-table th{background:#eff3e9;font-weight:400;color:var(--jade-muted);text-align:left}.ke-ad-table th,.ke-ad-table td{padding:16px;border-bottom:1px solid var(--jade-line)}.ke-ad-table .admin-title{white-space:normal;min-width:220px;max-width:420px;line-height:1.8}.ke-ad-table tr:hover td{background:#f9fbf5}.ke-ad-table a{color:var(--jade-600)}.admin-state{padding:70px 25px;text-align:center;border:1px solid var(--jade-line);color:var(--jade-muted);font-size:13px;background:#fffefa}.admin-state button{margin-top:20px}@media(max-width:1000px){.ke-ad-stats{grid-template-columns:repeat(3,minmax(0,1fr))}.admin-topline{align-items:flex-start;flex-direction:column}}@media(max-width:600px){.ke-ad-stats{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ke-ad-stat{padding:18px}.ke-ad-tabs{gap:5px}.ke-ad-tabs button{font-size:11px;padding:8px 11px}}
</style>
